// Generated by build.rs; clippy is exempted for generated code only.
#[allow(clippy::all)]
mod generated {
    include!(concat!(env!("OUT_DIR"), "/svg_builder.rs"));
    include!(concat!(env!("OUT_DIR"), "/svg_builder.serde.rs"));
}
pub use generated::*;

/// `parameters.proto` as a `FileDescriptorSet`, for consumers that walk the schema at runtime.
pub const DESCRIPTOR: &[u8] = include_bytes!(concat!(env!("OUT_DIR"), "/descriptor.bin"));

use crate::Error;
use crate::blueprint::style::MATRIX_COLOR;
use crate::color::hex_rgba;
use crate::mood::Mood;

pub fn parse(text: &str) -> Result<Parameters, serde_json::Error> {
    serde_json::from_str(text)
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Glyph {
    Hexatri { rotate: bool },
    Ship,
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub enum Ground {
    Trihex {
        motion: trihex::Motion,
        image: trihex::Image,
    },
}

#[derive(Debug, Clone, PartialEq)]
pub struct Rain {
    pub angle: f64,
    pub color: String,
}

#[derive(Debug, Clone, PartialEq)]
pub struct Scene {
    pub seed: u32,
    pub ground: Ground,
    pub glyph: Glyph,
    pub overlay: Option<Rain>,
}

impl Scene {
    /// True when the ground, the glyph or the overlay belongs to `mood`.
    pub fn uses(&self, mood: Mood) -> bool {
        let ground = match self.ground {
            Ground::Trihex { .. } => Mood::Blueprint,
        };
        let glyph = match self.glyph {
            Glyph::Hexatri { .. } | Glyph::Ship => Mood::Blueprint,
        };
        // matrix is the only overlay
        let overlay = self.overlay.as_ref().map(|_| Mood::Blueprint);
        [Some(ground), Some(glyph), overlay].contains(&Some(mood))
    }

    /// Legacy lowercase vocabulary: it names the output files (STARFIELD is `space`).
    pub fn slug(&self) -> String {
        let Ground::Trihex { motion, image } = self.ground;
        let motion = match motion {
            trihex::Motion::Static => "static",
            trihex::Motion::Scan => "scan",
            trihex::Motion::Lights => "lights",
            trihex::Motion::Closeopen => "closeopen",
        };
        let (fg, icon) = match self.glyph {
            Glyph::Hexatri { rotate: true } => ("rotate", "hexatri"),
            Glyph::Hexatri { rotate: false } => ("static", "hexatri"),
            Glyph::Ship => ("static", "ship"),
        };
        let image = match image {
            trihex::Image::None => "none",
            trihex::Image::Starfield => "space",
        };
        let overlay = if self.overlay.is_some() {
            "matrix"
        } else {
            "none"
        };
        format!("{motion}-{fg}-{icon}-{image}-{overlay}")
    }
}

fn trihex_of(p: &Parameters) -> Trihex {
    match p.background.as_ref().and_then(|b| b.ground.as_ref()) {
        Some(background::Ground::Trihex(t)) => *t,
        None => Trihex::default(),
    }
}

pub fn resolve(p: &Parameters) -> Scene {
    let bg = trihex_of(p);
    let glyph = match p.icon.as_ref().and_then(|i| i.glyph.as_ref()) {
        Some(icon::Glyph::Ship(_)) => Glyph::Ship,
        Some(icon::Glyph::Hexatri(h)) => Glyph::Hexatri {
            rotate: h.motion() == hexatri::Motion::Rotate,
        },
        None => Glyph::Hexatri { rotate: true },
    };
    let overlay =
        p.overlay
            .as_ref()
            .and_then(|o| o.layer.as_ref())
            .map(|overlay::Layer::Matrix(m)| Rain {
                angle: m.angle,
                color: if m.color.is_empty() {
                    MATRIX_COLOR.to_string()
                } else {
                    m.color.clone()
                },
            });
    Scene {
        seed: p.seed,
        ground: Ground::Trihex {
            motion: bg.motion(),
            image: bg.image(),
        },
        glyph,
        overlay,
    }
}

/// The rules parameters.proto cannot state. Prefer moving a field over adding a check here.
pub fn validate(p: &Parameters) -> Result<(), Error> {
    let bg = trihex_of(p);
    if bg.motion() == trihex::Motion::Closeopen && bg.image() == trihex::Image::None {
        return Err(Error::Invalid(
            "background.trihex.motion CLOSEOPEN has nothing to reveal with background.trihex.image NONE \
             (its hexagons open onto an image); set image STARFIELD, or motion LIGHTS"
                .into(),
        ));
    }
    if let Some(overlay::Layer::Matrix(m)) = p.overlay.as_ref().and_then(|o| o.layer.as_ref()) {
        if !(0.0..=360.0).contains(&m.angle) {
            return Err(Error::Invalid(format!(
                "overlay.matrix.angle {} is outside 0-360 \
                 (0 = falling down, increasing clockwise)",
                crate::geom::fmt(m.angle)
            )));
        }
        let color = if m.color.is_empty() {
            MATRIX_COLOR
        } else {
            &m.color
        };
        hex_rgba(color).map_err(|e| Error::Invalid(format!("overlay.matrix.color: {e}")))?;
    }

    let check = |s: &str, field: &str| -> Result<(), Error> {
        parse_res(s)
            .map(|_| ())
            .map_err(|e| Error::Invalid(format!("{field}: {e}")))
    };
    match p.output.as_ref().and_then(|o| o.sink.as_ref()) {
        Some(output::Sink::File(f)) => check(&f.resolution, "output.file.resolution")?,
        Some(output::Sink::Stdout(s)) => check(&s.resolution, "output.stdout.resolution")?,
        Some(output::Sink::Directory(d)) => {
            for r in &d.resolutions {
                check(r, "output.directory.resolutions")?;
            }
        }
        None => {}
    }
    Ok(())
}

/// The resolution presets, in UI order. `parse_res` reads this too, so accepted == offered.
pub const RESOLUTIONS: [(&str, (u32, u32)); 8] = [
    ("1080p", (1920, 1080)),
    ("1440p", (2560, 1440)),
    ("4k", (3840, 2160)),
    ("720p", (1280, 720)),
    ("mobile", (1080, 1920)),
    ("square", (1080, 1080)),
    ("tablet", (1536, 2048)),
    ("ultrawide", (3440, 1440)),
];

/// Empty -> 1080p, else a preset name or WIDTHxHEIGHT. Zero dimensions are rejected.
pub fn parse_res(s: &str) -> Result<(u32, u32), Error> {
    // Default on the raw input, before trimming: whitespace-only is rejected, as in Python.
    let s = if s.is_empty() { "1080p" } else { s };
    let s = s.trim().to_lowercase();
    let s = s.as_str();
    if let Some((_, wh)) = RESOLUTIONS.iter().find(|(name, _)| *name == s) {
        return Ok(*wh);
    }
    let bad = || {
        let names: Vec<&str> = RESOLUTIONS.iter().map(|(n, _)| *n).collect();
        Error::Invalid(format!(
            "bad resolution '{s}': use WIDTHxHEIGHT or a preset {names:?}"
        ))
    };
    let (w, h) = s.split_once('x').ok_or_else(bad)?;
    let (w, h) = (
        w.parse::<u32>().map_err(|_| bad())?,
        h.parse::<u32>().map_err(|_| bad())?,
    );
    if w == 0 || h == 0 {
        return Err(Error::Invalid(format!(
            "bad resolution '{s}': both dimensions must be non-zero"
        )));
    }
    Ok((w, h))
}

/// Every config the schema expresses and `validate` keeps; both test sweeps enumerate from here.
/// Matrix angle and colour are non-default on purpose: defaults would skip the code they pin.
pub fn valid_configs(seed: u32) -> Vec<serde_json::Value> {
    use serde_json::json;
    let mut out = Vec::new();
    // Dense enums: walking until try_from fails is declaration order.
    for motion in (0..).map_while(|i| trihex::Motion::try_from(i).ok()) {
        for image in (0..).map_while(|i| trihex::Image::try_from(i).ok()) {
            if motion == trihex::Motion::Closeopen && image == trihex::Image::None {
                continue; // rejected by validate(), though renderable
            }
            for glyph in [
                json!({"hexatri": {"motion": "ROTATE"}}),
                json!({"hexatri": {"motion": "STATIC"}}),
                json!({"ship": {}}),
            ] {
                for overlay in [
                    json!({}),
                    json!({"matrix": {"angle": 250, "color": "#395e53cc"}}),
                ] {
                    out.push(json!({
                        "seed": seed,
                        "background": {"trihex": {"motion": motion.as_str_name(), "image": image.as_str_name()}},
                        "icon": glyph,
                        "overlay": overlay,
                    }));
                }
            }
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn the_schema_rejects_what_it_cannot_represent() {
        assert!(parse(r#"{"icon":{"ship":{"motion":"ROTATE"}}}"#).is_err());
        assert!(parse(r#"{"overlay":{"angle":90}}"#).is_err());
        assert!(parse(r#"{"output":{"file":{"path":"a.svg"},"stdout":{}}}"#).is_err());
        assert!(parse(r#"{"backgrond":{}}"#).is_err());
        assert!(parse(r#"{"background":{"trihex":{"motion":"SPIRAL"}}}"#).is_err());
    }

    #[test]
    fn the_old_flat_background_is_rejected() {
        assert!(parse(r#"{"background":{"motion":"SCAN"}}"#).is_err());
    }

    #[test]
    fn an_empty_config_is_a_complete_config() {
        let p = parse("{}").expect("{} must parse");
        assert_eq!(p.seed, 0);
        assert_eq!(trihex_of(&p).motion(), trihex::Motion::Static);
        assert!(p.icon.is_none());
        assert_eq!(
            trihex_of(
                &parse(r#"{"background":{"trihex":{"motion":"CLOSEOPEN","image":"STARFIELD"}}}"#)
                    .unwrap()
            )
            .motion(),
            trihex::Motion::Closeopen
        );
    }

    #[test]
    fn an_empty_config_resolves_to_the_old_defaults() {
        let s = resolve(&parse("{}").unwrap());
        assert_eq!(s.seed, 0);
        assert_eq!(
            s.ground,
            Ground::Trihex {
                motion: trihex::Motion::Static,
                image: trihex::Image::None,
            }
        );
        assert_eq!(s.glyph, Glyph::Hexatri { rotate: true });
        assert!(s.overlay.is_none());
        assert_eq!(s.slug(), "static-rotate-hexatri-none-none");
    }

    #[test]
    fn a_full_config_resolves_every_axis() {
        let s = resolve(
            &parse(
                r##"{"seed":7,"background":{"trihex":{"motion":"CLOSEOPEN","image":"STARFIELD"}},
                    "icon":{"ship":{}},
                    "overlay":{"matrix":{"angle":250,"color":"#395e53cc"}}}"##,
            )
            .unwrap(),
        );
        assert_eq!(s.seed, 7);
        assert_eq!(s.glyph, Glyph::Ship);
        assert_eq!(s.slug(), "closeopen-static-ship-space-matrix");
        let rain = s.overlay.unwrap();
        assert_eq!(rain.angle, 250.0);
        assert_eq!(rain.color, "#395e53cc");

        let s = resolve(&parse(r#"{"overlay":{"matrix":{"angle":0}}}"#).unwrap());
        assert_eq!(
            s.overlay.unwrap().color,
            crate::blueprint::style::MATRIX_COLOR
        );

        // STATIC -> rotate:false; a swapped variant would pass every other test.
        let s = resolve(&parse(r#"{"icon":{"hexatri":{"motion":"STATIC"}}}"#).unwrap());
        assert_eq!(s.glyph, Glyph::Hexatri { rotate: false });
    }

    #[test]
    fn validate_rejects_what_the_schema_cannot() {
        for bad in [
            r#"{"background":{"trihex":{"motion":"CLOSEOPEN","image":"NONE"}}}"#,
            r#"{"overlay":{"matrix":{"angle":400}}}"#,
            r#"{"overlay":{"matrix":{"angle":-1}}}"#,
            r#"{"overlay":{"matrix":{"color":"395e53"}}}"#,
            r#"{"output":{"directory":{"resolutions":["1080"]}}}"#,
            r#"{"output":{"stdout":{"resolution":"0x0"}}}"#,
        ] {
            assert!(validate(&parse(bad).unwrap()).is_err(), "accepted {bad}");
        }
        assert!(
            validate(
                &parse(r#"{"background":{"trihex":{"motion":"CLOSEOPEN","image":"STARFIELD"}}}"#)
                    .unwrap()
            )
            .is_ok()
        );
    }

    #[test]
    fn parse_res_takes_presets_and_dimensions() {
        assert_eq!(parse_res("").unwrap(), (1920, 1080));
        assert_eq!(parse_res("4K").unwrap(), (3840, 2160));
        assert_eq!(parse_res(" 1280x720 ").unwrap(), (1280, 720));
        for bad in ["1080", "1280x", "x720", "1280 x 720", "0x0", "1920x0", " "] {
            assert!(parse_res(bad).is_err(), "accepted {bad}");
        }
    }

    #[test]
    fn valid_configs_are_the_corpus() {
        let cfgs = valid_configs(0);
        assert_eq!(cfgs.len(), 42);
        assert_eq!(
            serde_json::to_string(&cfgs[0]).unwrap(),
            r#"{"background":{"trihex":{"image":"NONE","motion":"STATIC"}},"icon":{"hexatri":{"motion":"ROTATE"}},"overlay":{},"seed":0}"#
        );
        for c in &cfgs {
            let text = serde_json::to_string(c).unwrap();
            let p = parse(&text).unwrap_or_else(|e| panic!("{text}: {e}"));
            validate(&p).unwrap_or_else(|e| panic!("{text}: {e}"));
        }
    }

    #[test]
    fn resolutions_is_what_parse_res_accepts() {
        assert_eq!(RESOLUTIONS.len(), 8);
        for (name, wh) in RESOLUTIONS {
            assert_eq!(parse_res(name).unwrap(), wh, "preset {name}");
        }
        let msg = parse_res("nope").unwrap_err().to_string();
        for (name, _) in RESOLUTIONS {
            assert!(
                msg.contains(name),
                "error message omits preset {name}: {msg}"
            );
        }
    }
}
